using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using System.Linq;using System.Collections.Generic;using System.IO;
internal class CommandScript:IRunCommand{
 const float step=.2f,x0=-20.1f,z0=-12.2f;const int nx=130,nz=304;Dictionary<string,Transform> named;List<string> lines=new List<string>();
 bool[,] Walk(){var a=new bool[nx,nz];for(int x=0;x<nx;x++)for(int z=0;z<nz;z++){var p=new Vector3(x0+x*step,0,z0+z*step);a[x,z]=Physics.Raycast(p+Vector3.up*.08f,Vector3.down,.35f,~0,QueryTriggerInteraction.Ignore)&&!Physics.CheckCapsule(p+Vector3.up*.35f,p+Vector3.up*1.5f,.29f,~0,QueryTriggerInteraction.Ignore);}return a;}
 HashSet<Vector2Int> Reach(Vector2 start){var map=Walk();int sx=Mathf.RoundToInt((start.x-x0)/step),sz=Mathf.RoundToInt((start.y-z0)/step);var seen=new HashSet<Vector2Int>();var q=new Queue<Vector2Int>();q.Enqueue(new Vector2Int(sx,sz));seen.Add(new Vector2Int(sx,sz));while(q.Count>0){var p=q.Dequeue();foreach(var d in new[]{Vector2Int.up,Vector2Int.down,Vector2Int.left,Vector2Int.right}){var n=p+d;if(n.x<0||n.y<0||n.x>=nx||n.y>=nz||seen.Contains(n)||!map[n.x,n.y])continue;seen.Add(n);q.Enqueue(n);}}return seen;}
 bool Has(HashSet<Vector2Int> set,float x,float z)=>set.Contains(new Vector2Int(Mathf.RoundToInt((x-x0)/step),Mathf.RoundToInt((z-z0)/step)));
 void C(bool b,string s)=>lines.Add((b?"PASS ":"FAIL ")+s);
 public void Execute(ExecutionResult r){var all=Resources.FindObjectsOfTypeAll<Transform>().Where(t=>t.gameObject.scene==SceneManager.GetActiveScene()).ToArray();named=all.GroupBy(t=>t.name).ToDictionary(g=>g.Key,g=>g.First());var names=new[]{"R3 permanently unlocked exit solid leaf","R3 arrival rear solid leaf","R3 Hub exit only solid leaf","R2 Anchor gallery access solid panel","P3 Gate A alternative route solid panel","P3 Gate B final hold solid panel"};var gates=names.Select(n=>named[n]).ToArray();var poses=gates.Select(t=>t.position).ToArray();var hub=named["R1 Clinical Observation Hub"].gameObject;bool active=hub.activeSelf;
 try{Physics.SyncTransforms();var set=Reach(new Vector2(0,-8));C(!Has(set,-18.6f,-9.5f)&&!Has(set,2.5f,18)&&!Has(set,-5.05f,46),"Fresh Hub cannot bypass P1 or enter R3/late route");
 hub.SetActive(true);gates[0].position+=Vector3.up*3.05f;gates[1].position+=Vector3.up*3.05f;gates[3].position+=Vector3.up*3.05f;Physics.SyncTransforms();set=Reach(new Vector2(0,-8));C(!Has(set,-7,-9.5f)&&!Has(set,-18.6f,-9.5f),"unlocked R3 receiving phase blocks Hub reverse entry");set=Reach(new Vector2(-5.7f,27.8f));C(Has(set,-7.8f,43)&&!Has(set,-5.05f,46)&&!Has(set,-18.6f,46),"R1 with R3 retained cannot bypass closed P3 A/B");
 gates[1].position=poses[1];gates[2].position+=Vector3.up*3.05f;Physics.SyncTransforms();set=Reach(new Vector2(0,-8));C(Has(set,-7,-9.5f)&&!Has(set,-18.6f,-9.5f)&&!Has(set,-5.05f,46),"releasing phase permits vestibule only; rear prevents all late-route entry");
 gates[4].position+=Vector3.up*3.05f;Physics.SyncTransforms();set=Reach(new Vector2(-5.7f,27.8f));C(Has(set,-5.05f,39.5f)&&!Has(set,-5.05f,46),"A open B closed still blocks P3 payoff and R3");gates[5].position+=Vector3.up*3.05f;gates[1].position+=Vector3.up*3.05f;gates[2].position=poses[2];Physics.SyncTransforms();set=Reach(new Vector2(-5.7f,27.8f));C(Has(set,-18.6f,-9.5f)&&Has(set,-7,-9.5f),"valid A/B route reaches full R3 spine and arrival vestibule");
 }finally{for(int i=0;i<gates.Length;i++)gates[i].position=poses[i];hub.SetActive(active);Physics.SyncTransforms();}File.WriteAllLines("/tmp/echo-vs1-r3/topology.txt",lines);r.Log(string.Join("\n",lines));}}
